CREATE VIEW dq_missing_play_status AS SELECT dg.GameID, gir.game_title AS GameTitle, gir.platform_name AS PlatformName, gir.owned_flag, gir.access_status, gir.play_status_raw, gir.play_status FROM std_inventory_game_ready AS gir INNER JOIN Game AS dg ON ((dg.GameTitle = gir.game_title)) WHERE ((gir.owned_flag = CAST('t' AS BOOLEAN)) AND (gir.access_status = 'Available') AND ((gir.play_status IS NULL) OR (main."trim"(gir.play_status) = ''))) ORDER BY gir.game_title, gir.platform_name;
